contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depAmount)); require(depAmount <= 1000000000000000000000000000000);
        require(depAmount > 0, "deposit must be positive");
        require(address(this).balance >= depAmount, "not enough balance to deposit");

        uint beforeContractBalance = address(c).balance;

        c.deposit{value: depAmount}(); if (__ESBMC_reverted()) return;

        uint afterDepositContractBalance = address(c).balance;

        bool withdrawReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        uint afterContractBalance = address(c).balance;

        assert(
            withdrawReverted
                ? afterContractBalance == afterDepositContractBalance
                : afterContractBalance == beforeContractBalance
        );
    }

    receive() external payable {}
}

