// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depAmount) internal {
        depAmount = bound(depAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depAmount > 0);
        vm.assume(address(this).balance >= depAmount);
        uint beforeContractBalance = address(c).balance;
        try c.deposit{value: depAmount}() {} catch { return; }
        uint afterDepositContractBalance = address(c).balance;
        bool withdrawReverted;
        try c.withdrawAll() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint afterContractBalance = address(c).balance;
        assertTrue(withdrawReverted
                ? afterContractBalance == afterDepositContractBalance
                : afterContractBalance == beforeContractBalance);
    }

    function testFuzz_run(uint256 depAmount) public {
        _run(depAmount);
    }

    receive() external payable {}
}
